// ===== app/actions/todo.ts （服务端） =====
'use server'

import { revalidatePath } from 'next/cache'

export type Todo = { id: string; title: string; done: boolean }

// 模拟数据库（真实项目换成 Prisma / Drizzle 等）
const db: Todo[] = [
  { id: '1', title: '学习 Server Actions', done: false },
]

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms))

export async function getTodos(): Promise<Todo[]> {
  return [...db]
}

export async function addTodo(title: string): Promise<Todo> {
  await delay(600) // 模拟网络/数据库延迟
  const trimmed = title.trim()
  if (!trimmed) throw new Error('标题不能为空')   // 服务端校验是安全边界

  const todo: Todo = { id: crypto.randomUUID(), title: trimmed, done: false }
  db.push(todo)
  revalidatePath('/')  // 让 Server Component 重新取数
  return todo
}

export async function toggleTodo(id: string): Promise<void> {
  await delay(400)
  const target = db.find((t) => t.id === id)
  if (target) target.done = !target.done
  revalidatePath('/')
}


// ===== app/todo-list.tsx （客户端） =====
'use client'

import { useOptimistic, useTransition, useRef } from 'react'
import { useFormStatus } from 'react-dom'
import { addTodo, toggleTodo, type Todo } from './actions/todo'

// SubmitButton 必须是 <form> 的子组件，useFormStatus 才能读到 pending
function SubmitButton() {
  const { pending } = useFormStatus()
  return (
    <button type="submit" disabled={pending}>
      {pending ? '添加中…' : '添加'}
    </button>
  )
}

export default function TodoList({ todos }: { todos: Todo[] }) {
  // 1) 乐观状态：真实数据是 todos，本地先"假装"已添加
  const [optimisticTodos, addOptimisticTodo] = useOptimistic(
    todos,
    (state: Todo[], newTitle: string): Todo[] => [
      ...state,
      { id: `temp-${Date.now()}`, title: newTitle, done: false }, // 临时 id 做 key
    ]
  )

  const [isPending, startTransition] = useTransition()
  const formRef = useRef<HTMLFormElement>(null)

  // 2) 表单 action：先乐观更新，再调用 Server Action
  function handleAdd(formData: FormData) {
    const title = String(formData.get('title') ?? '')
    startTransition(async () => {
      addOptimisticTodo(title)
      await addTodo(title)          // 失败时 React 自动回滚乐观值
      formRef.current?.reset()      // 成功后清空输入框
    })
  }

  return (
    <section style={{ maxWidth: 420 }}>
      <form ref={formRef} action={handleAdd} style={{ display: 'flex', gap: 8 }}>
        <input name="title" placeholder="新任务…" required />
        <SubmitButton />
      </form>

      <ul style={{ opacity: isPending ? 0.6 : 1, transition: 'opacity .15s' }}>
        {optimisticTodos.map((t) => (
          <li key={t.id}>
            <label>
              <input
                type="checkbox"
                checked={t.done}
                onChange={() => startTransition(() => toggleTodo(t.id))}
              />
              {t.title}
              {t.id.startsWith('temp-') ? ' （同步中）' : ''}
            </label>
          </li>
        ))}
      </ul>
    </section>
  )
}


// ===== app/page.tsx （服务端组件，负责首次取数） =====
import { getTodos } from './actions/todo'
import TodoList from './todo-list'

export default async function Page() {
  const todos = await getTodos()
  return (
    <main>
      <h1>今日任务</h1>
      <TodoList todos={todos} />
    </main>
  )
}


// ===== app/error.tsx （必须有！捕获 Action 抛出的错误） =====
'use client'

export default function Error({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div>
      <p>出错了：{error.message}</p>
      <button onClick={reset}>重试</button>
    </div>
  )
}

